(() => {
  const $ = id => document.getElementById(id);
  const escape = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const values = (names, before, after, changed=-1) => `<table><thead><tr><th>Variable</th><th>Before</th><th>After</th></tr></thead><tbody>${names.map((n,i)=>`<tr ${i===changed?'class="changed"':''}><th>${n}</th><td>${before[i]}</td><td>${after[i]}${i===changed?' <span class="change-label">written</span>':''}</td></tr>`).join('')}</tbody></table>`;
  const examples = {
    hello:{code:'printf("Hello, C!\\n");',html:'<p>Console output:</p><pre>Hello, C!</pre>',question:'Which escape sequence starts a new line?',choices:['\\n','/n','\\t'],answer:0,why:'The backslash-n escape writes a newline. Keep it inside the quoted string.'},
    loops:{code:'int total = 0;\nfor (int i = 1; i <= 5; i++) {\n    total += i;\n}',html:'<p>Running total:</p><pre>0 → 1 → 3 → 6 → 10 → 15</pre>',question:'If n is 3, what will sum_to(n) return?',choices:['3','6','9'],answer:1,why:'The loop adds 1 + 2 + 3, which is 6.'},
    pointers:{code:'int temp = *a;\n*a = *b;\n*b = temp;',html:values(['*a (first integer)','*b (second integer)'],[10,42],[42,10]),question:'Start with 10 at a and 42 at b. After int temp = *a; then *a = *b;, what is temp?',choices:['10','42','It has no value'],answer:0,why:'temp holds a separate copy of the original 10. Writing through a does not change that copy.',steps:[
      {code:'int temp = *a;',caption:'Save the first value before overwriting it.',html:values(['*a','*b','temp'],[10,42,'not declared'],[10,42,10],2)},
      {code:'*a = *b;',caption:'Copy the second value into the first location. Only *a changes.',html:values(['*a','*b','temp'],[10,42,10],[42,42,10],0)},
      {code:'*b = temp;',caption:'Write the saved value into the second location. The swap is complete.',html:values(['*a','*b','temp'],[42,42,10],[42,10,10],1)}]},
    heap:{code:'int *values = malloc(n * sizeof *values);\nif (!values) return 1;\n// Fill and use values before releasing it.\nfree(values);',html:'<p>For n = 5, fill the allocation before reading it:</p><pre>1  4  9  16  25</pre><p>After free(values), do not access these elements.</p>',question:'What must happen before you read values[0] after malloc?',choices:['Assign a value to it','Call free(values)','Nothing: malloc fills it with zero'],answer:0,why:'malloc does not initialize the elements. Check the allocation succeeded, then write each element before reading it.'},
    search:{code:'int a[] = {2, 5, 8, 12, 16, 23, 38, 56};\n// Target: 23\n// Inspect index 3: 12 < 23 → search indices 4–7.\n// Inspect index 5: 23 == 23 → return 5.',html:'<p>Search interval:</p><pre>indices 0–7 → indices 4–7 → found at 5</pre>',question:'The middle value is smaller than the target. Which part can you discard?',choices:['The middle and everything before it','Everything after the middle','Neither part'],answer:0,why:'The array is sorted. All values at or before the middle are too small. Continue at mid + 1.',steps:[
      {code:'lo = 0; hi = 7;',caption:'Start with all eight sorted elements as candidates.',html:'<pre>2  5  8  12  16  23  38  56</pre>'},
      {code:'mid = 3; lo = mid + 1;',caption:'a[3] is 12, which is smaller than 23. Discard indices 0–3.',html:'<pre><s>2  5  8  12</s>  16  23  38  56</pre>'},
      {code:'mid = 5; return mid;',caption:'a[5] matches the target. Return its index, not its value.',html:'<pre>16  <mark>23</mark>  38  56</pre>'}]},
    sort:{code:'// Insert 2 into the sorted prefix [9].\nint key = a[1];      // 2\na[1] = a[0];        // shift 9 right\na[0] = key;         // insert 2',html:'<p>Before:</p><pre>9  2  7  1  5</pre><p>After the first insertion:</p><pre><strong>2  9</strong>  7  1  5</pre>',question:'After the first insertion, how many elements belong to the sorted prefix?',choices:['1','2','5'],answer:1,why:'The prefix [2, 9] is sorted. The remaining elements still need to be inserted.',steps:[
      {code:'key = 2;',caption:'Save the next value, 2.',html:'<pre>9  <mark>2</mark>  7  1  5</pre>'},
      {code:'a[1] = a[0];',caption:'Shift the larger value, 9, one position to the right.',html:'<pre>9  <mark>9</mark>  7  1  5    key = 2</pre>'},
      {code:'a[0] = key;',caption:'Insert the saved 2 into the opening.',html:'<pre><mark>2</mark>  9  7  1  5</pre>'}]},
    rows:{code:'Row row;\nscanf("%d %31s", &row.id, row.name);\nprintf("%d | %s\\n", row.id, row.name);',html:'<p>Input: <code>1 Ada</code></p><table><thead><tr><th>row.id</th><th>row.name</th></tr></thead><tbody><tr><td>1</td><td>Ada</td></tr></tbody></table>',question:'Why is the input width 31 when name has room for 32 characters?',choices:['One position is needed for the zero terminator','The first element cannot be used','scanf counts from one'],answer:0,why:'A C string ends with a zero byte. A maximum of 31 input characters leaves space for it.'},
    query:{code:'insert 1 Ada\ninsert 2 Grace\nselect 2',html:'<p>Inspect row 0: ID 1 does not match.</p><p>Inspect row 1: ID 2 matches.</p><pre>2 | Grace</pre>',question:'Which index should find_row return for ID 2 after these inserts?',choices:['0','1','2'],answer:1,why:'Array indexing starts at zero. ID 2 is stored at index 1; return the index so the caller can access that row.'}
  };
  let current, step=0;
  function renderStep(){const frames=current.steps,frame=frames[step];$('step-caption').textContent=frame.caption;$('step-state').innerHTML=frame.html;$('step-code').textContent=frame.code;$('step-position').textContent=`${step+1} / ${frames.length}`;$('step-back').disabled=step===0;$('step-next').textContent=step===frames.length-1?'Try it yourself ↓':'Next step →';}
  function show(id){current=examples[id];step=0;$('worked-code').textContent=current.code;$('worked-diagram').innerHTML=current.html;$('step-details').open=false;$('step-details').hidden=!current.steps;if(current.steps)renderStep();$('prediction-options').innerHTML=`<legend>${escape(current.question)}</legend>${current.choices.map((c,i)=>`<label><input type="radio" name="prediction" value="${i}"> ${escape(c)}</label>`).join('')}`;$('prediction-feedback').textContent='';}
  $('step-back').onclick=()=>{step=Math.max(0,step-1);renderStep();};
  $('step-reset').onclick=()=>{step=0;renderStep();};
  $('step-next').onclick=()=>{if(step===current.steps.length-1){$('step-details').open=false;$('exercise-title').scrollIntoView({block:'start'});$('editor').focus({preventScroll:true});}else{step++;renderStep();}};
  $('prediction-check').onclick=()=>{const choice=document.querySelector('input[name="prediction"]:checked');$('prediction-feedback').textContent=choice?`${Number(choice.value)===current.answer?'Correct.':'Not quite.'} ${current.why}`:'Choose an answer first.';};
  function comparisons(n){let lo=0,hi=n-1,count=0;while(lo<=hi){count++;const mid=lo+Math.floor((hi-lo)/2);if(mid===n-1)break;lo=mid+1;}return count;}
  function updateComplexity(){const n=2**Number($('complexity-size').value),b=comparisons(n);$('complexity-n').textContent=`${n.toLocaleString()} elements`;$('search-comparison').innerHTML=`<table><thead><tr><th>List size</th><th>Linear comparisons</th><th>Binary comparisons</th></tr></thead><tbody><tr><td>${n.toLocaleString()}</td><td>${n.toLocaleString()}</td><td>${b}</td></tr><tr><td>${(n*2).toLocaleString()} (doubled)</td><td>${(n*2).toLocaleString()}</td><td>${comparisons(n*2)}</td></tr></tbody></table>`;$('doubling-note').textContent=`Doubling from ${n} to ${n*2}: linear adds ${n} comparisons; binary adds ${comparisons(n*2)-b}.`;}
  $('complexity-size').oninput=updateComplexity;
  window.lessonVisuals={show,updateComplexity};
})();
